package in.kabadiwala.connect.integration; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import software.amazon.awssdk.services.s3.S3Client; import software.amazon.awssdk.services.s3.model.*; import software.amazon.awssdk.core.sync.RequestBody; import java.util.*; @Service @ConditionalOnProperty(name="app.storage.provider",havingValue="s3") public class S3StorageService implements StorageService {private final S3Client s3=S3Client.create(); private final String bucket; public S3StorageService(@Value("${app.storage.s3.bucket}")String b){bucket=b;} public Stored store(MultipartFile f,String folder){try{String key=folder+"/"+UUID.randomUUID()+"-"+f.getOriginalFilename();s3.putObject(PutObjectRequest.builder().bucket(bucket).key(key).contentType(f.getContentType()).build(),RequestBody.fromBytes(f.getBytes()));return new Stored(key,"s3://"+bucket+"/"+key);}catch(Exception e){throw new IllegalArgumentException("Object storage upload failed");}} public byte[] read(String key){return s3.getObjectAsBytes(GetObjectRequest.builder().bucket(bucket).key(key).build()).asByteArray();}}
